<#
.SYNOPSIS
    CA Report-Only Policy Analyzer

.DESCRIPTION
    Reads real Entra ID sign-in log events and their own
    appliedConditionalAccessPolicies[] evaluation results to show which
    Conditional Access policies currently in report-only mode would
    actually have applied to a chosen set of users over a chosen window.

    It never infers or simulates a policy's behavior -- every number in
    the output traces back to a real Graph API evaluation result.

.PARAMETER SignInMethod
    "Auto" (default) tries device code sign-in first and automatically
    falls back to interactive browser sign-in if a tenant Conditional
    Access policy blocks the device code flow -- a policy Microsoft ships
    as a template and many tenants now enable, which otherwise leaves the
    device code screen failing with no obvious way forward. Pass
    "DeviceCode" or "Interactive" to skip the auto-detection and use one
    method directly (e.g. `.\analyzer.ps1 -SignInMethod Interactive`, or
    the same flag on the compiled .exe).
#>

param(
    [ValidateSet("Auto", "DeviceCode", "Interactive")]
    [string]$SignInMethod = "Auto"
)

Set-StrictMode -Version 1.0
$ProgressPreference = "SilentlyContinue"

# ===========================================================================
# Constants
# ===========================================================================

$Script:ClientId = "14d82eec-204b-4c2f-b7e8-296a70dab67e"
$Script:Scopes = "AuditLog.Read.All Policy.Read.All User.Read.All"
$Script:GraphBase = "https://graph.microsoft.com/v1.0"
$Script:AuthorityBase = "https://login.microsoftonline.com/organizations/oauth2/v2.0"

# Embedded so the exe/report/picker are fully self-contained -- no external asset files to lose.
$Script:AppIconBase64 = ""

# Every result value appliedConditionalAccessPolicies[].result can hold,
# per Microsoft Graph's documented enum. Anything outside this set is
# bucketed as "unknownFutureValue" -- never dropped, never merged into an
# existing bucket.
$Script:KnownResults = @(
    "reportOnlySuccess", "reportOnlyFailure", "reportOnlyNotApplied", "reportOnlyInterrupted",
    "success", "failure", "notApplied", "notEnabled"
)

# ===========================================================================
# Auth: device code flow
# ===========================================================================

function Get-DeviceCodeToken {
    $body = @{ client_id = $Script:ClientId; scope = $Script:Scopes }
    $flow = Invoke-RestMethod -Method Post -Uri "$($Script:AuthorityBase)/devicecode" `
        -Body $body -ContentType "application/x-www-form-urlencoded"

    Write-Host ""
    Write-Host $flow.message -ForegroundColor Cyan
    Write-Host ""

    $interval = [int]$flow.interval
    if ($interval -lt 1) { $interval = 5 }
    $deadline = (Get-Date).AddSeconds([int]$flow.expires_in)

    while ((Get-Date) -lt $deadline) {
        Start-Sleep -Seconds $interval
        $tokenBody = @{
            grant_type  = "urn:ietf:params:oauth:grant-type:device_code"
            client_id   = $Script:ClientId
            device_code = $flow.device_code
        }
        try {
            $result = Invoke-RestMethod -Method Post -Uri "$($Script:AuthorityBase)/token" `
                -Body $tokenBody -ContentType "application/x-www-form-urlencoded" -ErrorAction Stop
            return $result.access_token
        } catch {
            $errBody = $null
            if ($_.ErrorDetails.Message) {
                try { $errBody = $_.ErrorDetails.Message | ConvertFrom-Json } catch { }
            }
            if ($null -eq $errBody) { throw }
            switch ($errBody.error) {
                "authorization_pending" { continue }
                "slow_down" { $interval += 5; continue }
                default { throw "Device code sign-in failed: $($errBody.error) - $($errBody.error_description)" }
            }
        }
    }
    throw "Device code sign-in timed out after $($flow.expires_in) seconds."
}

# A tenant Conditional Access policy can block the device code flow
# specifically (Microsoft ships this as a template policy, and it's
# increasingly common). The block surfaces only once the user finishes
# entering the code and signing in in their browser -- the /devicecode
# request itself always succeeds -- so it's detected here by inspecting
# the /token polling error, not up front.
function Test-DeviceCodeBlockedError {
    param([string]$Message)
    return $Message -match "(?i)AADSTS53003|conditional access"
}

# Interactive sign-in via the system browser using the OAuth
# authorization-code + PKCE flow (RFC 7636) and a loopback HTTP listener
# to catch the redirect -- the standard approach for public-client desktop
# apps (this is what MSAL.NET's system-browser flow and the Microsoft
# Graph PowerShell SDK's interactive Connect-MgGraph do under the hood).
# No client secret is used or needed; PKCE is what makes a public client
# safe without one. The redirect URI's registered form for this client is
# the bare loopback "http://localhost" -- Azure AD matches that against a
# request carrying any actual port, which is exactly why the listener can
# pick whatever port happens to be free rather than needing one
# pre-registered.
# Pure computation, split out from Get-InteractiveToken specifically so it
# can be unit tested without a listener or network call: the one thing
# that must never silently regress here is the challenge actually being
# derived from the verifier via SHA-256, since a wrong pairing fails
# closed at the token exchange with an opaque server-side error far away
# from this code.
function New-PkceChallenge {
    $verifierBytes = New-Object byte[] 32
    [System.Security.Cryptography.RandomNumberGenerator]::Create().GetBytes($verifierBytes)
    $verifier = [Convert]::ToBase64String($verifierBytes).TrimEnd('=').Replace('+', '-').Replace('/', '_')
    $sha256 = [System.Security.Cryptography.SHA256]::Create()
    $challengeBytes = $sha256.ComputeHash([System.Text.Encoding]::ASCII.GetBytes($verifier))
    $challenge = [Convert]::ToBase64String($challengeBytes).TrimEnd('=').Replace('+', '-').Replace('/', '_')
    return @{ Verifier = $verifier; Challenge = $challenge }
}

# Binds the loopback listener used to catch the OAuth redirect. Split out
# from Get-InteractiveToken so a test can bind it directly instead of
# going through a real browser + real tenant sign-in.
function Start-LoopbackListener {
    param([Nullable[int]]$FixedPort = $null)

    $listener = New-Object System.Net.HttpListener
    $port = $null
    $portsToTry = if ($FixedPort) { @($FixedPort) } else { 8766..8866 }
    foreach ($candidatePort in $portsToTry) {
        try {
            $listener.Prefixes.Clear()
            $listener.Prefixes.Add("http://localhost:$candidatePort/")
            $listener.Start()
            $port = $candidatePort
            break
        } catch { continue }
    }
    if (-not $port) { throw "Could not bind a local port for interactive sign-in." }
    return @{ Listener = $listener; Port = $port }
}

# Blocks until the redirect carrying either ?code=&state= or ?error=
# arrives, or MaxWaitSeconds elapses. Returns @{ Code = ... } or
# @{ CallbackError = "... " } -- never throws for a normal OAuth error
# response, only for a real timeout, so the caller decides how to surface
# each case. A request whose state doesn't match ExpectedState is treated
# as a stray hit on the port (e.g. a browser favicon fetch) rather than a
# valid callback, per OAuth CSRF protection -- it does not resolve the
# wait either way.
#
# Same BeginGetContext/WaitOne/EndGetContext polling pattern as
# Start-SelectionServer, and for the same reason: BeginGetContext must be
# called exactly once per connection, polled via WaitOne on that same
# IAsyncResult, and only re-issued after EndGetContext completes.
function Wait-ForAuthorizationCode {
    param(
        [Parameter(Mandatory)]$Listener,
        [Parameter(Mandatory)][string]$ExpectedState,
        [int]$MaxWaitSeconds = 300
    )

    $code = $null
    $callbackError = $null
    $deadline = (Get-Date).AddSeconds($MaxWaitSeconds)
    $pendingAccept = $Listener.BeginGetContext($null, $null)

    while ($null -eq $code -and $null -eq $callbackError) {
        if ((Get-Date) -gt $deadline) {
            throw "Interactive sign-in timed out after $MaxWaitSeconds second(s)."
        }
        $gotOne = $pendingAccept.AsyncWaitHandle.WaitOne(500)
        if (-not $gotOne) { continue }

        $context = $Listener.EndGetContext($pendingAccept)
        $pendingAccept = $Listener.BeginGetContext($null, $null)
        $request = $context.Request
        $response = $context.Response

        $returnedState = $request.QueryString["state"]
        $returnedCode = $request.QueryString["code"]
        $returnedError = $request.QueryString["error"]
        $returnedErrorDesc = $request.QueryString["error_description"]

        if ($returnedError -and $returnedState -eq $ExpectedState) {
            $callbackError = "$returnedError - $returnedErrorDesc"
            $responseHtml = "<html><body><h2>Sign-in failed</h2><p>You can close this window and check the terminal.</p></body></html>"
        } elseif ($returnedCode -and $returnedState -eq $ExpectedState) {
            $code = $returnedCode
            $responseHtml = "<html><body><h2>Signed in</h2><p>You can close this window and return to the terminal.</p></body></html>"
        } else {
            # A stray request to this port (e.g. the browser fetching a
            # favicon, or a state that doesn't match) -- respond and keep
            # waiting for the real callback.
            $responseHtml = "<html><body></body></html>"
        }

        $buffer = [System.Text.Encoding]::UTF8.GetBytes($responseHtml)
        $response.ContentType = "text/html; charset=utf-8"
        $response.ContentLength64 = $buffer.Length
        $response.OutputStream.Write($buffer, 0, $buffer.Length)
        $response.OutputStream.Close()
    }

    if ($callbackError) { return @{ CallbackError = $callbackError } }
    return @{ Code = $code }
}

# Interactive sign-in via the system browser using the OAuth
# authorization-code + PKCE flow (RFC 7636) and a loopback HTTP listener
# to catch the redirect -- the standard approach for public-client desktop
# apps (this is what MSAL.NET's system-browser flow and the Microsoft
# Graph PowerShell SDK's interactive Connect-MgGraph do under the hood).
# No client secret is used or needed; PKCE is what makes a public client
# safe without one. The redirect URI's registered form for this client is
# the bare loopback "http://localhost" -- Azure AD matches that against a
# request carrying any actual port, which is exactly why the listener can
# pick whatever port happens to be free rather than needing one
# pre-registered.
function Get-InteractiveToken {
    $bound = Start-LoopbackListener
    $listener = $bound.Listener
    $redirectUri = "http://localhost:$($bound.Port)/"

    $pkce = New-PkceChallenge
    $state = [Guid]::NewGuid().ToString("N")

    $authParams = [ordered]@{
        client_id             = $Script:ClientId
        response_type         = "code"
        redirect_uri          = $redirectUri
        response_mode         = "query"
        scope                 = $Script:Scopes
        state                 = $state
        code_challenge        = $pkce.Challenge
        code_challenge_method = "S256"
        prompt                = "select_account"
    }
    $query = ($authParams.GetEnumerator() | ForEach-Object { "$($_.Key)=$([uri]::EscapeDataString($_.Value))" }) -join "&"
    $authUrl = "$($Script:AuthorityBase)/authorize?$query"

    Write-Host ""
    Write-Host "Opening your browser to sign in..." -ForegroundColor Cyan
    Write-Host "If it doesn't open automatically, go to this URL:" -ForegroundColor Cyan
    Write-Host $authUrl
    Write-Host ""
    try { Start-Process $authUrl | Out-Null } catch {
        Write-Host "Could not open a browser automatically -- open the URL above manually." -ForegroundColor Yellow
    }

    try {
        $result = Wait-ForAuthorizationCode -Listener $listener -ExpectedState $state -MaxWaitSeconds 300
    } finally {
        $listener.Stop()
        $listener.Close()
    }

    if ($result.CallbackError) { throw "Interactive sign-in failed: $($result.CallbackError)" }

    $tokenBody = @{
        client_id     = $Script:ClientId
        scope         = $Script:Scopes
        code          = $result.Code
        redirect_uri  = $redirectUri
        grant_type    = "authorization_code"
        code_verifier = $pkce.Verifier
    }
    try {
        $result = Invoke-RestMethod -Method Post -Uri "$($Script:AuthorityBase)/token" `
            -Body $tokenBody -ContentType "application/x-www-form-urlencoded" -ErrorAction Stop
        return $result.access_token
    } catch {
        $errBody = $null
        if ($_.ErrorDetails.Message) {
            try { $errBody = $_.ErrorDetails.Message | ConvertFrom-Json } catch { }
        }
        if ($errBody) { throw "Interactive sign-in failed exchanging the code: $($errBody.error) - $($errBody.error_description)" }
        throw
    }
}

function Get-AccessToken {
    param([string]$Method = "Auto")

    if ($Method -eq "Interactive") { return Get-InteractiveToken }
    if ($Method -eq "DeviceCode") { return Get-DeviceCodeToken }

    # Auto: device code first (works unattended, on any device), but a
    # growing number of tenants block it outright via Conditional Access,
    # in which case the sign-in appears to succeed in the browser and then
    # fails at the very last step with no obvious next action -- so that
    # specific failure gets a real fallback instead of just an error.
    try {
        return Get-DeviceCodeToken
    } catch {
        if (Test-DeviceCodeBlockedError -Message $_.Exception.Message) {
            Write-Host ""
            Write-Host "Device code sign-in was blocked by a Conditional Access policy in this tenant." -ForegroundColor Yellow
            Write-Host "Falling back to interactive browser sign-in..." -ForegroundColor Yellow
            return Get-InteractiveToken
        }
        throw
    }
}

# ===========================================================================
# Graph HTTP: retry/backoff + pagination
#
# Returns a plain hashtable rather than throwing typed exceptions for
# expected HTTP failure modes (403 / 429 / other) -- callers branch on
# .Success/.Reason explicitly. This keeps error handling simple and
# version-safe rather than relying on custom PowerShell class hierarchies.
# ===========================================================================

function Invoke-GraphRequestWithBackoff {
    param(
        [string]$Method = "GET",
        [Parameter(Mandatory)][string]$Uri,
        [Parameter(Mandatory)][hashtable]$Headers,
        [int]$MaxRetries = 5
    )
    for ($attempt = 1; $attempt -le $MaxRetries; $attempt++) {
        try {
            # -UseBasicParsing is required: without it, Windows PowerShell 5.1
            # tries to use Internet Explorer's DOM engine to parse the
            # response and can throw an interactive confirmation prompt on
            # first use in a session ("Script code in the web page might be
            # run..."). In any non-interactive context (or a fresh machine
            # where IE's first-run hasn't been dismissed) that prompt cannot
            # be answered and the call fails/hangs -- found only by actually
            # running this end to end, not by reading the code.
            $response = Invoke-WebRequest -Method $Method -Uri $Uri -Headers $Headers -UseBasicParsing -ErrorAction Stop
            $parsed = $response.Content | ConvertFrom-Json
            return @{ Success = $true; Data = $parsed }
        } catch {
            $webResponse = $_.Exception.Response
            if ($null -eq $webResponse) {
                return @{ Success = $false; Reason = "network"; Message = $_.Exception.Message }
            }
            $statusCode = [int]$webResponse.StatusCode

            if ($statusCode -eq 403) {
                return @{ Success = $false; Reason = "permission"; Message = "$Method $Uri -> 403" }
            }
            if ($statusCode -eq 429) {
                if ($attempt -eq $MaxRetries) {
                    return @{ Success = $false; Reason = "throttled"; Message = "$Method $Uri exhausted $MaxRetries retries on 429" }
                }
                $retryAfter = 1
                if ($webResponse.Headers["Retry-After"]) { $retryAfter = [int]$webResponse.Headers["Retry-After"] }
                Start-Sleep -Seconds $retryAfter
                continue
            }
            return @{ Success = $false; Reason = "other"; Message = "$Method $Uri -> $statusCode" }
        }
    }
}

function Get-GraphAllPages {
    param(
        [Parameter(Mandatory)][string]$Uri,
        [Parameter(Mandatory)][hashtable]$Headers,
        # Invoked after each page with the running total -- lets callers
        # print progress on long pulls (e.g. a full-tenant sign-in log
        # pull) without this function knowing anything about how progress
        # should be displayed.
        [scriptblock]$OnPage = $null
    )
    $results = New-Object System.Collections.ArrayList
    $nextUri = $Uri
    while ($nextUri) {
        $resp = Invoke-GraphRequestWithBackoff -Uri $nextUri -Headers $Headers
        if (-not $resp.Success) {
            return @{ Success = $false; Reason = $resp.Reason; Message = $resp.Message; Data = @($results) }
        }
        if ($resp.Data.value) {
            [void]$results.AddRange(@($resp.Data.value))
        }
        if ($OnPage) { & $OnPage $results.Count }
        $nextUri = $resp.Data.'@odata.nextLink'
    }
    return @{ Success = $true; Data = @($results) }
}

# ===========================================================================
# Discovery + sign-in log fetch functions
# ===========================================================================

function Get-CaPolicies {
    param([hashtable]$Headers)
    return Get-GraphAllPages -Uri "$($Script:GraphBase)/identity/conditionalAccess/policies" -Headers $Headers
}

function Get-DiscoveryUsers {
    param([hashtable]$Headers)
    return Get-GraphAllPages -Uri "$($Script:GraphBase)/users?`$select=id,displayName,userPrincipalName" -Headers $Headers
}

function Get-SignInsForUser {
    param([hashtable]$Headers, [string]$UserPrincipalName, [string]$SinceIso, [scriptblock]$OnPage = $null)
    $filter = "userPrincipalName eq '$UserPrincipalName' and createdDateTime ge $SinceIso"
    $encodedFilter = [System.Uri]::EscapeDataString($filter)
    return Get-GraphAllPages -Uri "$($Script:GraphBase)/auditLogs/signIns?`$filter=$encodedFilter" -Headers $Headers -OnPage $OnPage
}

function Get-SignInsAll {
    param([hashtable]$Headers, [string]$SinceIso, [scriptblock]$OnPage = $null)
    $filter = "createdDateTime ge $SinceIso"
    $encodedFilter = [System.Uri]::EscapeDataString($filter)
    return Get-GraphAllPages -Uri "$($Script:GraphBase)/auditLogs/signIns?`$filter=$encodedFilter" -Headers $Headers -OnPage $OnPage
}

# ===========================================================================
# Aggregation -- pure logic, no I/O. Three-state honesty:
# evaluated / not evaluated / not collected, never collapsed.
# ===========================================================================

function Get-ResultBucket {
    param([string]$RawResult)
    if ($Script:KnownResults -contains $RawResult) { return $RawResult }
    return "unknownFutureValue"
}

function Find-AppliedPolicyEntry {
    param($SignIn, [string]$PolicyId)
    if (-not $SignIn.appliedConditionalAccessPolicies) { return $null }
    foreach ($entry in $SignIn.appliedConditionalAccessPolicies) {
        if ($entry.id -eq $PolicyId) { return $entry }
    }
    return $null
}

function Format-SignInLocation {
    param($SignIn)
    $city = "Unknown"
    $country = "Unknown"
    if ($SignIn.location) {
        if ($SignIn.location.city) { $city = $SignIn.location.city }
        if ($SignIn.location.countryOrRegion) { $country = $SignIn.location.countryOrRegion }
    }
    return "$city, $country"
}

function Get-SignInDateKey {
    param($SignIn)
    # Real Graph createdDateTime is ISO 8601 ("2026-08-01T10:00:00Z"); the
    # first 10 characters are always the date part regardless of exact
    # sub-second precision. Falls back to "unknown" rather than throwing
    # on a missing/malformed value -- a report can't chart a date it
    # doesn't have, but it must not crash over one bad record either.
    $raw = $SignIn.createdDateTime
    if ([string]::IsNullOrEmpty($raw) -or ([string]$raw).Length -lt 10) { return "unknown" }
    return ([string]$raw).Substring(0, 10)
}

function Get-AggregateCell {
    param([array]$SignIns, [string]$PolicyId, [int]$MaxSamples = 50)

    $counts = @{}
    $notEvaluatedCount = 0
    $sampleEvents = New-Object System.Collections.ArrayList
    # Per-day, per-result-bucket counts across ALL sign-ins (not just the
    # capped samples) -- powers the report's daily impact timeline. Built
    # from the same loop that already visits every sign-in, so this adds
    # no new collection, just a second breakdown of data already in hand.
    $dailyCounts = @{}

    foreach ($signIn in $SignIns) {
        $entry = Find-AppliedPolicyEntry -SignIn $signIn -PolicyId $PolicyId
        if ($null -eq $entry) {
            $notEvaluatedCount++
            $bucket = "not_evaluated"
        } else {
            $bucket = Get-ResultBucket -RawResult $entry.result
            if ($counts.ContainsKey($bucket)) { $counts[$bucket]++ } else { $counts[$bucket] = 1 }
        }

        $dateKey = Get-SignInDateKey -SignIn $signIn
        if (-not $dailyCounts.ContainsKey($dateKey)) { $dailyCounts[$dateKey] = @{} }
        if ($dailyCounts[$dateKey].ContainsKey($bucket)) { $dailyCounts[$dateKey][$bucket]++ } else { $dailyCounts[$dateKey][$bucket] = 1 }

        if ($sampleEvents.Count -lt $MaxSamples) {
            $deviceCompliant = $null
            if ($signIn.deviceDetail -and ($null -ne $signIn.deviceDetail.isCompliant)) {
                $deviceCompliant = $signIn.deviceDetail.isCompliant
            }
            [void]$sampleEvents.Add(@{
                timestamp        = $signIn.createdDateTime
                app              = $signIn.appDisplayName
                location         = Format-SignInLocation -SignIn $signIn
                deviceCompliant  = $deviceCompliant
                resultBucket     = $bucket
            })
        }
    }

    return @{
        notCollected      = $false
        counts            = $counts
        notEvaluatedCount = $notEvaluatedCount
        totalSignIns      = $SignIns.Count
        sampleEvents      = @($sampleEvents)
        dailyCounts       = $dailyCounts
    }
}

function Get-UserPolicyMatrix {
    param(
        [array]$Users,
        [array]$Policies,
        [hashtable]$SignInsByUser,
        [hashtable]$CollectionErrors,
        [int]$MaxSamples = 50
    )
    $matrix = @{}
    foreach ($user in $Users) {
        $userId = $user.id
        $matrix[$userId] = @{}

        if ($CollectionErrors.ContainsKey($userId)) {
            $marker = @{ notCollected = $true; reason = $CollectionErrors[$userId] }
            foreach ($policy in $Policies) { $matrix[$userId][$policy.id] = $marker }
            continue
        }

        $signIns = @()
        if ($SignInsByUser.ContainsKey($userId)) { $signIns = $SignInsByUser[$userId] }
        foreach ($policy in $Policies) {
            $matrix[$userId][$policy.id] = Get-AggregateCell -SignIns $signIns -PolicyId $policy.id -MaxSamples $MaxSamples
        }
    }
    return $matrix
}

function Get-PolicyTotals {
    param([hashtable]$Matrix, [string]$PolicyId)
    $counts = @{}
    $notEvaluatedCount = 0
    $notCollectedUsers = 0
    $totalSignIns = 0
    $dailyCounts = @{}

    foreach ($userId in $Matrix.Keys) {
        $cell = $Matrix[$userId][$PolicyId]
        if ($cell.notCollected) {
            $notCollectedUsers++
            continue
        }
        foreach ($bucket in $cell.counts.Keys) {
            if ($counts.ContainsKey($bucket)) { $counts[$bucket] += $cell.counts[$bucket] }
            else { $counts[$bucket] = $cell.counts[$bucket] }
        }
        $notEvaluatedCount += $cell.notEvaluatedCount
        $totalSignIns += $cell.totalSignIns

        if ($cell.dailyCounts) {
            foreach ($dateKey in $cell.dailyCounts.Keys) {
                if (-not $dailyCounts.ContainsKey($dateKey)) { $dailyCounts[$dateKey] = @{} }
                foreach ($bucket in $cell.dailyCounts[$dateKey].Keys) {
                    if ($dailyCounts[$dateKey].ContainsKey($bucket)) { $dailyCounts[$dateKey][$bucket] += $cell.dailyCounts[$dateKey][$bucket] }
                    else { $dailyCounts[$dateKey][$bucket] = $cell.dailyCounts[$dateKey][$bucket] }
                }
            }
        }
    }

    return @{
        counts            = $counts
        notEvaluatedCount = $notEvaluatedCount
        notCollectedUsers = $notCollectedUsers
        totalSignIns      = $totalSignIns
        dailyCounts       = $dailyCounts
    }
}

# ===========================================================================
# User-scope resolution (all users, or specific users)
# ===========================================================================

function Resolve-UserScope {
    param(
        [hashtable]$Selection,
        [array]$DiscoveredUsers
    )
    # PowerShell gotcha: a bare array `return`ed from a function is silently
    # unwrapped to a scalar when it holds exactly one (or zero) elements.
    # Every return path here uses the unary comma operator `,` to force the
    # caller to always receive a real array, regardless of element count.
    if ($Selection.all_users) { return , @($DiscoveredUsers) }

    $usersById = @{}
    foreach ($u in $DiscoveredUsers) { $usersById[$u.id] = $u }

    $selectedIds = New-Object System.Collections.Specialized.OrderedDictionary

    foreach ($userId in $Selection.user_ids) {
        if ($usersById.ContainsKey($userId)) { $selectedIds[$userId] = $true }
    }

    $result = New-Object System.Collections.ArrayList
    foreach ($id in $selectedIds.Keys) { [void]$result.Add($usersById[$id]) }
    return , @($result)
}

# ===========================================================================
# Shared HTML helpers
# ===========================================================================

# JSON destined for an inline <script> block must never let a literal
# "</script>" close the tag early -- this bit us for real in an earlier
# version of this tool, so it's applied everywhere JSON is embedded,
# proactively, not discovered after the fact.
function ConvertTo-ScriptSafeJson {
    param($InputObject, [int]$Depth = 12)
    # Two real PowerShell/ConvertTo-Json quirks, both caught by testing, both
    # specific to the TOP-LEVEL value handed to ConvertTo-Json (a nested
    # array buried inside a larger object -- e.g. Get-ReportHtml's
    # $reportData.matrix[...].sampleEvents -- is NOT affected, verified
    # directly; only the root value is):
    #   1. An empty array returns $null, not the string "[]".
    #   2. A ONE-element array serializes as a bare JSON OBJECT, not a
    #      one-element JSON array -- e.g. a tenant with exactly one
    #      discovered user or exactly one report-only policy would embed
    #      `{"id":...}` where the page's JS expects `[{"id":...}]`, and
    #      `for (const item of items)` throws "items is not iterable".
    # Building the array by hand for any array-typed input, regardless of
    # element count, sidesteps both cases uniformly instead of chasing
    # each count as its own special case.
    if ($InputObject -is [array]) {
        if ($InputObject.Count -eq 0) { return "[]" }
        $parts = foreach ($item in $InputObject) {
            $itemJson = $item | ConvertTo-Json -Depth $Depth -Compress
            if ($null -eq $itemJson) { $itemJson = "null" }
            $itemJson.Replace("</script>", "<\/script>")
        }
        return "[" + ($parts -join ",") + "]"
    }
    $json = $InputObject | ConvertTo-Json -Depth $Depth -Compress
    if ($null -eq $json) { return "[]" }
    return $json.Replace("</script>", "<\/script>")
}

