# Report renderer
# ===========================================================================

$Script:ReportPageStyle = @'
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');
  :root {
    --bg: #f7f8fa; --card: #ffffff; --border: #e3e6ea;
    --text: #1c2128; --text-muted: #5b6572;
    --accent: #4A90C8; --accent-soft: rgba(74,144,200,0.08);
    /* Real GBG palette, matched from the main assessment tool's own report
       CSS -- consistency across the tool family beats a bespoke palette. */
    --ok: #4FAE7E; --ok-soft: rgba(79,174,126,0.12); --ok-border: rgba(79,174,126,0.35);
    --bad: #C81E2C; --bad-soft: rgba(200,30,44,0.12); --bad-border: rgba(200,30,44,0.35);
    --warn: #E8954A; --warn-soft: rgba(232,149,74,0.12); --warn-border: rgba(232,149,74,0.35);
    --neutral: #6b7280; --neutral-soft: #eef0f2; --neutral-border: #d7dbe0;
  }
  * { box-sizing: border-box; }
  body {
    font-family: 'Inter', -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    background: var(--bg); color: var(--text);
    margin: 0; padding: 2.5rem 1.5rem 4rem;
  }
  .page { max-width: 1100px; margin: 0 auto; }
  .brand-row { display: flex; align-items: center; gap: 0.75rem; margin: 0 0 0.6rem; }
  .brand-row img { width: 40px; height: 40px; flex-shrink: 0; }
  h1 { font-size: 1.75rem; font-weight: 700; margin: 0; letter-spacing: -0.01em; }
  h2 {
    font-size: 1.05rem; font-weight: 700; margin: 2rem 0 0.9rem;
    padding: 0.5rem 0.85rem; border-left: 4px solid var(--accent);
    background: var(--accent-soft); border-radius: 0 6px 6px 0;
  }
  h3 { font-size: 1rem; font-weight: 700; margin: 1.5rem 0 0.75rem; }
  .headline { font-size: 1.05rem; color: var(--text-muted); margin: 0 0 1.5rem; max-width: 760px; }
  .headline strong { color: var(--text); }
  .cards { display: flex; gap: 0.9rem; flex-wrap: wrap; margin-bottom: 0.5rem; }
  .stat-card {
    background: var(--card); border: 1px solid var(--border); border-radius: 12px;
    padding: 0.9rem 1.2rem; min-width: 140px;
    box-shadow: 0 1px 2px rgba(16,24,40,0.04);
  }
  .stat-card .label { font-size: 0.78rem; color: var(--text-muted); margin-bottom: 0.25rem; }
  .stat-card .value { font-size: 1.5rem; font-weight: 700; }
  .stat-card.warn .value { color: var(--warn); }

  /* Policy verdict cards -- the primary view */
  .verdict-card {
    background: var(--card); border: 1px solid var(--border); border-radius: 12px;
    padding: 1rem 1.25rem; margin-bottom: 0.75rem;
    box-shadow: 0 1px 2px rgba(16,24,40,0.04);
  }
  .verdict-card-head { display: flex; align-items: center; justify-content: space-between; gap: 1rem; cursor: pointer; }
  .verdict-policy-name { font-weight: 600; font-size: 0.95rem; }
  .verdict-badge {
    display: inline-flex; align-items: center; gap: 0.4rem;
    padding: 0.3rem 0.7rem; border-radius: 999px; font-size: 0.78rem; font-weight: 600;
    white-space: nowrap; border: 1px solid transparent;
  }
  .verdict-badge .dot { width: 7px; height: 7px; border-radius: 50%; flex-shrink: 0; }
  .verdict-affect  { background: var(--bad-soft);  color: var(--bad);  border-color: var(--bad-border); }
  .verdict-affect  .dot { background: var(--bad); }
  .verdict-unknown { background: var(--warn-soft); color: var(--warn); border-color: var(--warn-border); }
  .verdict-unknown .dot { background: var(--warn); }
  .verdict-none    { background: var(--neutral-soft); color: var(--neutral); border-color: var(--neutral-border); }
  .verdict-none    .dot { background: var(--neutral); }
  .verdict-ready   { background: var(--ok-soft);   color: var(--ok);   border-color: var(--ok-border); }
  .verdict-ready   .dot { background: var(--ok); }
  .verdict-detail { display: none; margin-top: 0.9rem; padding-top: 0.9rem; border-top: 1px solid var(--border); font-size: 0.85rem; }
  .verdict-detail.open { display: block; }
  .affected-user-row {
    display: flex; justify-content: space-between; padding: 0.4rem 0; border-bottom: 1px solid var(--border);
    cursor: pointer;
  }
  .affected-user-row:last-child { border-bottom: none; }
  .affected-user-row:hover { color: var(--accent); }
  .verdict-note { color: var(--text-muted); font-size: 0.82rem; margin-top: 0.5rem; }

  details.detail-toggle {
    background: var(--card); border: 1px solid var(--border); border-radius: 12px;
    padding: 1rem 1.25rem; margin-top: 1.5rem;
  }
  details.detail-toggle summary { cursor: pointer; font-weight: 600; font-size: 0.9rem; }
  details.detail-toggle[open] summary { margin-bottom: 1rem; }

  table { border-collapse: collapse; width: 100%; background: var(--card); border-radius: 12px; overflow: hidden; }
  th, td { border: 1px solid var(--border); padding: 0.6rem 0.8rem; text-align: left; font-size: 0.85rem; vertical-align: top; }
  th { background: var(--neutral-soft); font-weight: 600; }
  tbody tr:hover td, tr:hover td { background: var(--accent-soft); }
  td.cell-would-apply { background: var(--ok-soft); }
  td.cell-would-not-apply { background: var(--bad-soft); }
  td.cell-mixed { background: var(--warn-soft); }
  td.cell-not-collected { background: var(--neutral-soft); color: var(--text-muted); font-style: italic; }
  td.matrix-cell { cursor: pointer; }
  td.matrix-cell:hover { filter: brightness(0.97); }
  #drill-down {
    display: none; background: var(--card); border: 1px solid var(--border); border-radius: 12px;
    padding: 1rem 1.25rem; margin-top: 0.9rem; font-size: 0.85rem;
  }
  #drill-down table { margin-top: 0.6rem; }
  .policy-chart { background: var(--card); border: 1px solid var(--border); border-radius: 12px; padding: 1rem 1.25rem; margin-bottom: 0.9rem; }
  .policy-chart h3 { margin: 0 0 0.75rem; font-size: 0.95rem; }

  /* Verdict summary donut */
  .donut-wrap { display: flex; align-items: center; gap: 1.5rem; background: var(--card); border: 1px solid var(--border); border-radius: 12px; padding: 1rem 1.5rem; margin-bottom: 1.25rem; }
  .donut-svg { flex-shrink: 0; }
  .donut-total { font-size: 1.4rem; font-weight: 700; fill: var(--text); }
  .donut-legend { display: flex; flex-direction: column; gap: 0.4rem; font-size: 0.85rem; }
  .donut-legend-row { display: flex; align-items: center; gap: 0.5rem; }
  .legend-dot { width: 10px; height: 10px; border-radius: 50%; flex-shrink: 0; }

  /* Segmented result-distribution bar (mini on cards, full in the detail section) */
  .segmented-bar { display: flex; width: 100%; height: 14px; border-radius: 7px; overflow: hidden; background: var(--neutral-soft); margin-top: 0.6rem; }
  .segmented-bar .segment { height: 100%; }

  /* Daily impact timeline */
  .timeline-label { font-size: 0.78rem; color: var(--text-muted); margin: 0.8rem 0 0.4rem; }
  .timeline-chart { display: flex; align-items: flex-end; gap: 3px; height: 70px; background: var(--card); border: 1px solid var(--border); border-radius: 8px; padding: 0.5rem; }
  .timeline-col { flex: 1; height: 100%; display: flex; align-items: flex-end; min-width: 4px; }
  .timeline-track { width: 100%; background: var(--neutral-soft); border-radius: 2px 2px 0 0; display: flex; align-items: flex-end; overflow: hidden; }
  .timeline-impact { width: 100%; background: var(--bad); }
  .mini-stat-row { font-size: 0.82rem; margin-top: 0.3rem; }
  .caveats {
    background: var(--warn-soft); border: 1px solid #eccf94; border-radius: 10px;
    padding: 1rem 1.25rem; margin-top: 2rem;
  }
  .caveats strong { display: block; margin-bottom: 0.4rem; }
  .caveats ul { margin: 0; padding-left: 1.2rem; font-size: 0.85rem; color: var(--text-muted); }
  .caveats li { margin-bottom: 0.3rem; }
</style>
'@

function Get-ReportHtml {
    param([hashtable]$Matrix, [array]$Users, [array]$Policies, [hashtable]$Meta)

    $policyTotals = @{}
    foreach ($policy in $Policies) {
        $policyTotals[$policy.id] = Get-PolicyTotals -Matrix $Matrix -PolicyId $policy.id
    }

    $reportData = @{
        users        = @($Users)
        policies     = @($Policies)
        matrix       = $Matrix
        policyTotals = $policyTotals
        meta         = $Meta
    }
    $reportJson = ConvertTo-ScriptSafeJson -InputObject $reportData

    # NOTE: this is a single-quoted (non-interpolating) here-string on
    # purpose. PowerShell's interpolating `@" ... "@` here-strings treat
    # `${...}` as ITS OWN variable-interpolation syntax -- which collides
    # head-on with JavaScript's `${...}` template-literal syntax used
    # throughout the embedded script below. That collision was caught by
    # testing (it crashed with "variable not set" errors), not guessed.
    # Real values are substituted afterward via .Replace() on placeholder
    # tokens instead -- same pattern the project's earlier Python version
    # used for exactly this reason.
    $template = @'
<!doctype html>
<html>
<head>
<meta charset="utf-8">
<title>CA Report-Only Policy Analyzer -- Report</title>
__REPORT_STYLE__
</head>
<body>
<div class="page">
  <div class="brand-row"><img src="data:image/png;base64,__APP_ICON_BASE64__" alt=""><h1>CA Report-Only Policy Analyzer -- Report</h1></div>
  <p class="headline" id="headline-sentence"></p>
  <div class="cards" id="summary-cards"></div>

  <h2>Report-Only Policies</h2>
  <div id="verdict-summary-chart"></div>
  <div id="policy-verdicts"></div>

  <details class="detail-toggle">
    <summary>Show full user &times; policy matrix and per-policy result distribution</summary>
    <h3>User &times; Policy Matrix</h3>
    <table id="matrix-table"></table>
    <div id="drill-down"></div>

    <h3>Per-Policy Result Distribution</h3>
    <div id="policy-charts"></div>
  </details>

  <div class="caveats">
    <strong>Caveats</strong>
    <ul>
      <li>Results assume each policy's report-only/enforced mode was constant across the analyzed window -- Graph only exposes the current policy list, not its history.</li>
      <li>Interactive user sign-ins only; workload-identity/service-principal sign-ins are not included.</li>
      <li>"Not evaluated" means this policy's conditions (app, resource, risk level, scope, etc.) did not match that specific sign-in -- it is never the same thing as "would not apply to this user in general," and it is not evidence anything is broken.</li>
      <li>"Zero impact" means none of the pulled sign-ins would have had a different outcome -- it does not mean the policy was checked against every possible scenario, only the sign-ins actually observed in this window.</li>
      <li>This tool does not independently verify whether the tenant's sign-in log retention actually covered the full requested day range.</li>
    </ul>
  </div>
</div>

<script>
  const REPORT_DATA = __REPORT_DATA__;

  function escapeHtml(str) {
    const div = document.createElement("div");
    div.textContent = (str === null || str === undefined) ? "" : String(str);
    return div.innerHTML;
  }

  // Mirrors the CSS custom properties in the <style> block -- JS can't
  // read var(--x) values without a getComputedStyle round trip, and
  // hardcoding the same hex values directly is simpler and avoids
  // relying on browsers resolving CSS variables inside inline SVG
  // presentation attributes, which is inconsistent across engines.
  const PALETTE = {
    ok: "#4FAE7E", bad: "#C81E2C", warn: "#E8954A",
    neutral: "#9aa0a8", neutralLight: "#d7dbe0", accent: "#4A90C8",
  };
  const BUCKET_COLOR = {
    reportOnlySuccess: PALETTE.ok, success: PALETTE.ok,
    reportOnlyNotApplied: PALETTE.neutral, notApplied: PALETTE.neutral, notEnabled: PALETTE.neutral,
    reportOnlyFailure: PALETTE.bad, failure: PALETTE.bad,
    reportOnlyInterrupted: PALETTE.warn, unknownFutureValue: PALETTE.warn,
  };

  // Hand-rolled SVG donut -- overlapping <circle> elements with
  // stroke-dasharray/-dashoffset, the standard technique for a donut
  // chart without a charting library. A native <title> per segment gives
  // a real hover tooltip with no extra JS.
  function renderDonutChart(container, segments) {
    const total = segments.reduce((sum, s) => sum + s.value, 0);
    if (total === 0) {
      container.innerHTML = '<div class="hint">No policies to summarize.</div>';
      return;
    }
    const size = 148, radius = 54, stroke = 20, cx = size / 2, cy = size / 2;
    const circumference = 2 * Math.PI * radius;
    let offset = 0;
    let circles = "";
    for (const seg of segments) {
      if (seg.value === 0) continue;
      const dash = (seg.value / total) * circumference;
      circles += `<circle cx="${cx}" cy="${cy}" r="${radius}" fill="none" stroke="${seg.color}" ` +
        `stroke-width="${stroke}" stroke-dasharray="${dash} ${circumference - dash}" ` +
        `stroke-dashoffset="${-offset}" transform="rotate(-90 ${cx} ${cy})">` +
        `<title>${escapeHtml(seg.label)}: ${seg.value}</title></circle>`;
      offset += dash;
    }
    const svg = `<svg width="${size}" height="${size}" viewBox="0 0 ${size} ${size}" class="donut-svg">` +
      circles +
      `<text x="${cx}" y="${cy}" text-anchor="middle" dominant-baseline="central" class="donut-total">${total}</text>` +
      `</svg>`;
    const legend = segments.filter(s => s.value > 0).map(s =>
      `<div class="donut-legend-row"><span class="legend-dot" style="background:${s.color}"></span>${escapeHtml(s.label)}: ${s.value}</div>`
    ).join("");
    container.innerHTML = `<div class="donut-wrap">${svg}<div class="donut-legend">${legend}</div></div>`;
  }

  // A single segmented horizontal bar (one policy's whole result
  // distribution in one track) rather than a stack of separate skinny
  // bars -- denser, and the native title attribute gives per-segment
  // counts on hover without extra markup.
  function renderSegmentedBar(totals) {
    const counts = totals.counts || {};
    const total = Object.values(counts).reduce((a, b) => a + b, 0) + totals.notEvaluatedCount;
    if (total === 0) return '<div class="hint">No sign-ins evaluated against this policy.</div>';
    let segmentsHtml = "";
    for (const [bucket, count] of Object.entries(counts)) {
      if (count === 0) continue;
      const pct = (count / total) * 100;
      const color = BUCKET_COLOR[bucket] || PALETTE.accent;
      segmentsHtml += `<div class="segment" style="width:${pct}%;background:${color};" title="${escapeHtml(bucket)}: ${count}"></div>`;
    }
    if (totals.notEvaluatedCount > 0) {
      const naPct = (totals.notEvaluatedCount / total) * 100;
      segmentsHtml += `<div class="segment" style="width:${naPct}%;background:${PALETTE.neutralLight};" title="not_evaluated: ${totals.notEvaluatedCount}"></div>`;
    }
    return `<div class="segmented-bar">${segmentsHtml}</div>`;
  }

  // Daily impact timeline: one column per date the policy actually saw
  // sign-in activity on, a light full-height track for total evaluated
  // volume that day, with a red overlay proportional to how much of that
  // day's volume would have changed a real outcome (reportOnlyFailure /
  // reportOnlyInterrupted). Answers "was this concentrated on one day or
  // an ongoing pattern?" -- built from dailyCounts, which is a real count
  // across every sign-in pulled, not just the capped sample events.
  function renderTimeline(dailyCounts) {
    const dates = Object.keys(dailyCounts).filter(d => d !== "unknown").sort();
    if (dates.length === 0) return "";
    const dayTotal = dates.map(d => Object.values(dailyCounts[d]).reduce((a, b) => a + b, 0));
    const dayImpact = dates.map(d => sumBuckets(dailyCounts[d], IMPACT_BUCKETS));
    const maxTotal = Math.max(...dayTotal, 1);

    // Absolute pixel heights, not nested percentages -- a percentage
    // height on a flex child only resolves cleanly against an ancestor
    // whose own height is already a resolved pixel value, and chaining
    // that through .timeline-chart -> .timeline-col -> .timeline-track ->
    // .timeline-impact rendered the impact bar as full-height instead of
    // a proportional sliver when actually viewed (caught with a real
    // screenshot, not by reading the CSS). Computing both heights in
    // pixels against one known chart height sidesteps the ambiguity.
    const chartInnerHeightPx = 56;
    let cols = "";
    for (let i = 0; i < dates.length; i++) {
      const trackPx = Math.max(4, Math.round((dayTotal[i] / maxTotal) * chartInnerHeightPx));
      const impactPx = dayTotal[i] > 0 ? Math.round((dayImpact[i] / dayTotal[i]) * trackPx) : 0;
      const tooltip = `${dates[i]}: ${dayImpact[i]} impacting of ${dayTotal[i]} evaluated`;
      cols += `<div class="timeline-col" title="${escapeHtml(tooltip)}">` +
        `<div class="timeline-track" style="height:${trackPx}px;">` +
        `<div class="timeline-impact" style="height:${impactPx}px;"></div>` +
        `</div></div>`;
    }
    return `<div class="timeline-label">Daily impact (${escapeHtml(dates[0])} to ${escapeHtml(dates[dates.length - 1])})</div><div class="timeline-chart">${cols}</div>`;
  }

  // Device-compliance and location breakdown for a policy's impacting
  // sign-ins, built from sampleEvents (capped at 50 per user per policy)
  // rather than the full population -- stated explicitly in the output,
  // since this is a sample-based approximation, not an exhaustive count.
  function renderImpactBreakdown(policyId) {
    const events = [];
    for (const user of REPORT_DATA.users) {
      const cell = REPORT_DATA.matrix[user.id][policyId];
      if (cell.notCollected) continue;
      for (const e of (cell.sampleEvents || [])) {
        if (IMPACT_BUCKETS.includes(e.resultBucket)) events.push(e);
      }
    }
    if (events.length === 0) return "";

    const compliant = events.filter(e => e.deviceCompliant === true).length;
    const nonCompliant = events.filter(e => e.deviceCompliant === false).length;
    const unknownCompliance = events.length - compliant - nonCompliant;

    const locationCounts = {};
    for (const e of events) { locationCounts[e.location] = (locationCounts[e.location] || 0) + 1; }
    const topLocations = Object.entries(locationCounts).sort((a, b) => b[1] - a[1]).slice(0, 5);

    return `<div class="hint" style="margin-top:0.7rem;margin-bottom:0.3rem;">Based on ${events.length} sample event(s) available (capped at 50 per user) -- not necessarily every impacting sign-in:</div>` +
      `<div class="mini-stat-row">Device compliance: ${compliant} compliant, ${nonCompliant} non-compliant, ${unknownCompliance} unknown</div>` +
      `<div class="mini-stat-row">Top locations: ${topLocations.map(([loc, c]) => `${escapeHtml(loc)} (${c})`).join(", ")}</div>`;
  }

  function countNotCollectedUsers() {
    let count = 0;
    for (const userId of Object.keys(REPORT_DATA.matrix)) {
      const cells = Object.values(REPORT_DATA.matrix[userId]);
      if (cells.some(c => c.notCollected)) count++;
    }
    return count;
  }

  function renderSummaryCards() {
    const container = document.getElementById("summary-cards");
    const notCollected = countNotCollectedUsers();
    const cards = [
      ["Sign-ins pulled", REPORT_DATA.meta.totalSignIns, false],
      ["Users analyzed", REPORT_DATA.users.length, false],
      ["Not collected", notCollected, notCollected > 0],
      ["Report-only policies", REPORT_DATA.policies.length, false],
      ["Requested days", REPORT_DATA.meta.requestedDays, false],
    ];
    for (const [label, value, isWarn] of cards) {
      const div = document.createElement("div");
      div.className = "stat-card" + (isWarn ? " warn" : "");
      div.innerHTML = `<div class="label">${escapeHtml(label)}</div><div class="value">${escapeHtml(value)}</div>`;
      container.appendChild(div);
    }
  }

  // A policy's verdict is about REAL-WORLD IMPACT, not raw evaluation
  // counts: reportOnlySuccess/reportOnlyNotApplied mean "nothing would
  // change if this were enforced" (the sign-in already met the bar, or the
  // policy never targeted it). Only reportOnlyFailure/reportOnlyInterrupted
  // (or their non-report-only equivalents, kept for robustness even though
  // only report-only policies are ever analyzed) represent a sign-in that
  // would have had a DIFFERENT outcome. unknownFutureValue is deliberately
  // its own verdict rather than being silently folded into "ready" -- an
  // unrecognized Graph result string is not evidence of zero impact.
  const IMPACT_BUCKETS = ["reportOnlyFailure", "reportOnlyInterrupted", "failure"];

  function sumBuckets(counts, buckets) {
    return buckets.reduce((sum, b) => sum + (counts[b] || 0), 0);
  }

  function computeVerdict(totals) {
    const counts = totals.counts || {};
    const impact = sumBuckets(counts, IMPACT_BUCKETS);
    const unknown = counts.unknownFutureValue || 0;
    const totalEvaluated = Object.values(counts).reduce((a, b) => a + b, 0);

    if (unknown > 0) return { key: "unknown", impact, unknown };
    if (totalEvaluated === 0) return { key: "no-signal", impact: 0, unknown: 0 };
    if (impact > 0) return { key: "would-affect", impact, unknown: 0 };
    return { key: "ready", impact: 0, unknown: 0 };
  }

  const VERDICT_META = {
    "would-affect": { label: "Would have affected real sign-ins", cls: "verdict-affect", order: 0 },
    "unknown":      { label: "Unrecognized result -- needs manual review", cls: "verdict-unknown", order: 1 },
    "no-signal":    { label: "No usable signal in this window", cls: "verdict-none", order: 2 },
    "ready":        { label: "Zero impact -- ready to enforce", cls: "verdict-ready", order: 3 },
  };

  function findAffectedUsers(policyId) {
    const affected = [];
    for (const user of REPORT_DATA.users) {
      const cell = REPORT_DATA.matrix[user.id][policyId];
      if (cell.notCollected) continue;
      const counts = cell.counts || {};
      const impact = sumBuckets(counts, IMPACT_BUCKETS) + (counts.unknownFutureValue || 0);
      if (impact > 0) affected.push({ user, cell, impact });
    }
    affected.sort((a, b) => b.impact - a.impact);
    return affected;
  }

  function renderHeadline() {
    const verdicts = REPORT_DATA.policies.map(p => computeVerdict(REPORT_DATA.policyTotals[p.id]).key);
    const affectCount = verdicts.filter(v => v === "would-affect").length;
    const readyCount = verdicts.filter(v => v === "ready").length;
    const noSignalCount = verdicts.filter(v => v === "no-signal").length;
    const unknownCount = verdicts.filter(v => v === "unknown").length;

    const parts = [];
    if (affectCount > 0) {
      parts.push(`<strong>${affectCount}</strong> of ${REPORT_DATA.policies.length} report-only polic${affectCount === 1 ? "y" : "ies"} would have changed the outcome of at least one real sign-in`);
    } else {
      parts.push(`None of the ${REPORT_DATA.policies.length} report-only policies analyzed would have changed the outcome of any observed sign-in`);
    }
    const tail = [];
    if (readyCount > 0) tail.push(`${readyCount} had zero impact`);
    if (noSignalCount > 0) tail.push(`${noSignalCount} had no usable signal in this window`);
    if (unknownCount > 0) tail.push(`${unknownCount} returned an unrecognized result and need manual review`);
    const sentence = parts[0] + (tail.length ? "; " + tail.join(", ") + "." : ".");

    document.getElementById("headline-sentence").innerHTML = sentence;
  }

  function renderVerdictSummaryChart() {
    const counts = { "would-affect": 0, "ready": 0, "no-signal": 0, "unknown": 0 };
    for (const p of REPORT_DATA.policies) { counts[computeVerdict(REPORT_DATA.policyTotals[p.id]).key]++; }
    const segments = [
      { label: VERDICT_META["would-affect"].label, value: counts["would-affect"], color: PALETTE.bad },
      { label: VERDICT_META["ready"].label, value: counts["ready"], color: PALETTE.ok },
      { label: VERDICT_META["no-signal"].label, value: counts["no-signal"], color: PALETTE.neutral },
      { label: VERDICT_META["unknown"].label, value: counts["unknown"], color: PALETTE.warn },
    ];
    renderDonutChart(document.getElementById("verdict-summary-chart"), segments);
  }

  function toggleVerdictDetail(policyId) {
    const el = document.getElementById("verdict-detail-" + policyId);
    el.classList.toggle("open");
  }

  function renderPolicyVerdicts() {
    const container = document.getElementById("policy-verdicts");
    const rows = REPORT_DATA.policies.map(p => {
      const totals = REPORT_DATA.policyTotals[p.id];
      const verdict = computeVerdict(totals);
      return { policy: p, totals, verdict };
    });
    rows.sort((a, b) => VERDICT_META[a.verdict.key].order - VERDICT_META[b.verdict.key].order);

    for (const { policy, totals, verdict } of rows) {
      const meta = VERDICT_META[verdict.key];
      const card = document.createElement("div");
      card.className = "verdict-card";

      let countText = "";
      if (verdict.key === "would-affect") countText = `${verdict.impact} sign-in${verdict.impact === 1 ? "" : "s"}`;
      else if (verdict.key === "unknown") countText = `${verdict.unknown} unrecognized result${verdict.unknown === 1 ? "" : "s"}`;

      card.innerHTML =
        `<div class="verdict-card-head" onclick="toggleVerdictDetail('${policy.id}')">` +
        `<div class="verdict-policy-name">${escapeHtml(policy.displayName)}</div>` +
        `<div class="verdict-badge ${meta.cls}"><span class="dot"></span>${escapeHtml(meta.label)}${countText ? " (" + escapeHtml(countText) + ")" : ""}</div>` +
        `</div>` +
        renderSegmentedBar(totals) +
        `<div class="verdict-detail" id="verdict-detail-${policy.id}"></div>`;
      container.appendChild(card);

      const detailEl = card.querySelector(".verdict-detail");
      if (verdict.key === "would-affect" || verdict.key === "unknown") {
        const affected = findAffectedUsers(policy.id);
        const rowsHtml = affected.map(a =>
          `<div class="affected-user-row" onclick="showDrillDown(${JSON.stringify(a.user.id)}, ${JSON.stringify(policy.id)})">` +
          `<span>${escapeHtml(a.user.displayName)}</span><span>${a.impact} sign-in${a.impact === 1 ? "" : "s"}</span></div>`
        ).join("");
        detailEl.innerHTML = renderTimeline(totals.dailyCounts || {}) +
          renderImpactBreakdown(policy.id) +
          `<div style="margin-top:0.7rem;">Affected users (click for sample sign-ins):</div>${rowsHtml}`;
      } else if (verdict.key === "no-signal") {
        detailEl.innerHTML = `<div class="verdict-note">None of the ${REPORT_DATA.meta.totalSignIns} pulled sign-ins had any evaluation recorded for this policy -- it may target a scope (app, resource, identity type) this data never touched. Not evidence the policy is misconfigured.</div>`;
      } else {
        const totalEvaluated = Object.values(totals.counts || {}).reduce((a, b) => a + b, 0);
        detailEl.innerHTML = `<div class="verdict-note">${totalEvaluated} sign-in${totalEvaluated === 1 ? "" : "s"} evaluated against this policy; none would have had a different outcome if it were enforced.</div>`;
      }
      if (totals.notCollectedUsers > 0) {
        detailEl.innerHTML += `<div class="verdict-note">${totals.notCollectedUsers} user(s) could not be collected for this policy -- this verdict does not cover them.</div>`;
      }
    }
  }

  function dominantClass(cell) {
    if (cell.notCollected) return "cell-not-collected";
    const counts = cell.counts || {};
    const applyCount = (counts.reportOnlySuccess || 0) + (counts.success || 0);
    const notApplyCount = (counts.reportOnlyNotApplied || 0) + (counts.notApplied || 0) +
                           (counts.reportOnlyFailure || 0) + (counts.failure || 0);
    if (applyCount > 0 && notApplyCount === 0) return "cell-would-apply";
    if (notApplyCount > 0 && applyCount === 0) return "cell-would-not-apply";
    if (applyCount > 0 && notApplyCount > 0) return "cell-mixed";
    return "cell-not-collected";
  }

  function cellLabel(cell) {
    if (cell.notCollected) return "Not collected";
    const total = Object.values(cell.counts || {}).reduce((a, b) => a + b, 0);
    return `${total} evaluated / ${cell.notEvaluatedCount} not evaluated`;
  }

  function renderMatrix() {
    const table = document.getElementById("matrix-table");
    const headerRow = document.createElement("tr");
    headerRow.appendChild(document.createElement("th"));
    for (const policy of REPORT_DATA.policies) {
      const th = document.createElement("th");
      th.textContent = policy.displayName;
      headerRow.appendChild(th);
    }
    table.appendChild(headerRow);

    for (const user of REPORT_DATA.users) {
      const row = document.createElement("tr");
      const nameCell = document.createElement("td");
      nameCell.textContent = user.displayName;
      row.appendChild(nameCell);
      for (const policy of REPORT_DATA.policies) {
        const cell = REPORT_DATA.matrix[user.id][policy.id];
        const td = document.createElement("td");
        td.className = "matrix-cell " + dominantClass(cell);
        td.textContent = cellLabel(cell);
        td.addEventListener("click", () => showDrillDown(user, policy, cell));
        row.appendChild(td);
      }
      table.appendChild(row);
    }
  }

  function showDrillDown(user, policy, cell) {
    const el = document.getElementById("drill-down");
    if (cell.notCollected) {
      el.innerHTML = `<strong>${escapeHtml(user.displayName)} / ${escapeHtml(policy.displayName)}</strong>: not collected -- ${escapeHtml(cell.reason)}`;
    } else {
      const rows = (cell.sampleEvents || []).map(e =>
        `<tr><td>${escapeHtml(e.timestamp)}</td><td>${escapeHtml(e.app)}</td><td>${escapeHtml(e.location)}</td><td>${escapeHtml(e.resultBucket)}</td></tr>`
      ).join("");
      el.innerHTML = `<strong>${escapeHtml(user.displayName)} / ${escapeHtml(policy.displayName)}</strong> -- sample events:
        <table><tr><th>Time</th><th>App</th><th>Location</th><th>Result</th></tr>${rows}</table>`;
    }
    el.style.display = "block";
  }

  function renderPolicyCharts() {
    const container = document.getElementById("policy-charts");
    for (const policy of REPORT_DATA.policies) {
      const totals = REPORT_DATA.policyTotals[policy.id];
      const div = document.createElement("div");
      div.className = "policy-chart";
      let inner = `<h3>${escapeHtml(policy.displayName)}</h3>` + renderSegmentedBar(totals);
      if (totals.notCollectedUsers > 0) {
        inner += `<div class="hint">${totals.notCollectedUsers} user(s) not collected for this policy</div>`;
      }
      div.innerHTML = inner;
      container.appendChild(div);
    }
  }

  renderSummaryCards();
  renderHeadline();
  renderVerdictSummaryChart();
  renderPolicyVerdicts();
  renderMatrix();
  renderPolicyCharts();
</script>
</body>
</html>
'@

    $html = $template.Replace("__REPORT_STYLE__", $Script:ReportPageStyle).Replace("__REPORT_DATA__", $reportJson).Replace("__APP_ICON_BASE64__", $Script:AppIconBase64)
    return $html
}

function Write-ReportHtml {
    param([string]$Html, [string]$OutputPath)
    Set-Content -Path $OutputPath -Value $Html -Encoding UTF8 -NoNewline
}

# ===========================================================================
# Main orchestration
# ===========================================================================

function Invoke-CaReportOnlyAnalysis {
    param(
        [string]$OutputPath = "ca-report-only-analysis.html",
        [switch]$OpenBrowser = $true,
        [ValidateSet("Auto", "DeviceCode", "Interactive")]
        [string]$SignInMethod = "Auto"
    )

    Write-Host "=== CA Report-Only Policy Analyzer ===" -ForegroundColor Cyan
    Write-Host ""
    Write-Host "Signing in..."
    $token = Get-AccessToken -Method $SignInMethod
    $headers = @{ Authorization = "Bearer $token" }
    Write-Host "Signed in." -ForegroundColor Green
    Write-Host ""

    Write-Host "Discovering Conditional Access policies and users..."
    $policiesResp = Get-CaPolicies -Headers $headers
    if (-not $policiesResp.Success) {
        throw "Could not read Conditional Access policies: $($policiesResp.Reason) -- $($policiesResp.Message)"
    }
    $reportOnlyPolicies = @($policiesResp.Data | Where-Object { $_.state -eq "enabledForReportingButNotEnforced" })
    Write-Host "  $($reportOnlyPolicies.Count) report-only polic$(if ($reportOnlyPolicies.Count -eq 1) { 'y' } else { 'ies' }) found (of $($policiesResp.Data.Count) total CA policies)."

    $usersResp = Get-DiscoveryUsers -Headers $headers
    if (-not $usersResp.Success) {
        throw "Could not read users: $($usersResp.Reason) -- $($usersResp.Message)"
    }
    Write-Host "  $($usersResp.Data.Count) users found."
    Write-Host ""

    Write-Host "Opening the selection page in your browser..." -ForegroundColor Cyan
    $selection = Start-SelectionServer -Users $usersResp.Data -ReportOnlyPolicies $reportOnlyPolicies
    Write-Host "Selection received." -ForegroundColor Green
    Write-Host ""

    $scopedUsers = Resolve-UserScope -Selection $selection -DiscoveredUsers $usersResp.Data
    $selectedPolicyIdSet = @{}
    foreach ($id in $selection.policy_ids) { $selectedPolicyIdSet[$id] = $true }
    $reportPolicies = @($reportOnlyPolicies | Where-Object { $selectedPolicyIdSet.ContainsKey($_.id) })

    Write-Host "Analyzing $($scopedUsers.Count) user(s) against $($reportPolicies.Count) polic$(if ($reportPolicies.Count -eq 1) { 'y' } else { 'ies' }) over the last $($selection.days) day(s)."
    Write-Host ""

    $sinceIso = (Get-Date).ToUniversalTime().AddDays(-$selection.days).ToString("yyyy-MM-ddTHH:mm:ssZ")
    $signInsByUser = @{}
    $collectionErrors = @{}

    if ($selection.all_users) {
        Write-Host "Pulling sign-in logs for all users..."
        $onPage = { param($count) Write-Host "  $count sign-ins pulled so far..." }
        $allSignInsResp = Get-SignInsAll -Headers $headers -SinceIso $sinceIso -OnPage $onPage
        if (-not $allSignInsResp.Success) {
            $reason = "$($allSignInsResp.Reason): $($allSignInsResp.Message)"
            Write-Host "  Bulk pull failed ($reason) -- every selected user will be marked not collected." -ForegroundColor Yellow
            foreach ($user in $scopedUsers) { $collectionErrors[$user.id] = $reason }
        } else {
            $upnToUserId = @{}
            foreach ($user in $scopedUsers) { $upnToUserId[$user.userPrincipalName] = $user.id }
            foreach ($signIn in $allSignInsResp.Data) {
                $userId = $upnToUserId[$signIn.userPrincipalName]
                if ($userId) {
                    if (-not $signInsByUser.ContainsKey($userId)) { $signInsByUser[$userId] = New-Object System.Collections.ArrayList }
                    [void]$signInsByUser[$userId].Add($signIn)
                }
            }
            Write-Host "  Done -- $($allSignInsResp.Data.Count) total sign-ins pulled." -ForegroundColor Green
        }
    } else {
        $userIndex = 0
        foreach ($user in $scopedUsers) {
            $userIndex++
            Write-Host "Pulling sign-ins for $($user.displayName) ($userIndex of $($scopedUsers.Count))..."
            $resp = Get-SignInsForUser -Headers $headers -UserPrincipalName $user.userPrincipalName -SinceIso $sinceIso
            if (-not $resp.Success) {
                $reason = "$($resp.Reason): $($resp.Message)"
                Write-Host "  Failed ($reason) -- marked not collected." -ForegroundColor Yellow
                $collectionErrors[$user.id] = $reason
            } else {
                $signInsByUser[$user.id] = $resp.Data
                Write-Host "  $($resp.Data.Count) sign-ins pulled." -ForegroundColor Green
            }
        }
    }
    Write-Host ""

    Write-Host "Aggregating results..."
    # PowerShell array-unwrapping gotcha (found by testing, see
    # Resolve-UserScope): keep this as a real array with 0/1/N elements.
    $signInsByUserNormalized = @{}
    foreach ($key in $signInsByUser.Keys) { $signInsByUserNormalized[$key] = @($signInsByUser[$key]) }

    $matrix = Get-UserPolicyMatrix -Users $scopedUsers -Policies $reportPolicies -SignInsByUser $signInsByUserNormalized -CollectionErrors $collectionErrors
    $totalSignIns = 0
    foreach ($key in $signInsByUserNormalized.Keys) { $totalSignIns += $signInsByUserNormalized[$key].Count }

    $meta = @{
        totalSignIns  = $totalSignIns
        requestedDays = $selection.days
    }

    $html = Get-ReportHtml -Matrix $matrix -Users $scopedUsers -Policies $reportPolicies -Meta $meta
    Write-ReportHtml -Html $html -OutputPath $OutputPath

    Write-Host "Report written to $OutputPath" -ForegroundColor Green
    if ($OpenBrowser) {
        $fullPath = (Resolve-Path $OutputPath).Path
        try { Start-Process $fullPath | Out-Null } catch {
            Write-Host "Could not open the report automatically -- open it manually: $fullPath" -ForegroundColor Yellow
        }
    }

    return $OutputPath
}

# ===========================================================================
# Entry point
#
# Guarded so this file can be dot-sourced for testing without triggering a
# real sign-in -- $MyInvocation.InvocationName distinguishes being run
# directly (or via ps2exe) from being dot-sourced with `. .\analyzer.ps1`.
# ===========================================================================

if ($MyInvocation.InvocationName -ne ".") {
    Invoke-CaReportOnlyAnalysis -SignInMethod $SignInMethod
}
